syntax:
```c++
template <typename T>
struct SizeOf {
  static constexpr size_t value = sizeof(T);
};

int main() {
  constexpr size_t intSize = SizeOf<int>::value; // Compile-time evaluation
  constexpr size_t doubleSize = SizeOf<double>::value; // Compile-time evaluation
  std::cout << "Size of int: " << intSize << std::endl;
  std::cout << "Size of double: " << doubleSize << std::endl;
  return 0;
}
```

code_example:
template <typename T, typename U = void>
struct is_same_type {
  static constexpr bool value = false;
};

template <typename T>
struct is_same_type<T, T> {
  static constexpr bool value = true;
};

int main() {
  static_assert(is_same_type<int, int>::value, "Error: int is not equal to int");
  static_assert(!is_same_type<int, double>::value, "Error: int is equal to double");
  std::cout << std::is_same_v<int, int> << std::endl; // Using std::is_same_v
  return 0;
}

